};

class FEMultiMenu
{
  char layout[304];
public:
  virtual void Load();
};

class BoxText
{
public:
  void ReadFromFile(char *, bool);
  void makeBox(int, int, bool, float, int);
};

class PanelQuad
{
public:
  virtual void TurnOn(bool);
};

class CheatFrontEnd : public FEMultiMenu
{
public:
  void TurnOnPhone(bool);
};

class ExtrasFrontEnd : public FEMultiMenu
{
  stringx path;
  char layout0[104];
  BoxText *websites;
  CheatFrontEnd *cheat_menu;
  char layout1[88];
  PanelQuad *arrows[2][2];
public:
  virtual void Load();
  virtual void SetPQIndices();
};

void ExtrasFrontEnd::Load()
{
	FEMultiMenu::Load();
	SetPQIndices();

	stringx file = "websites";
//	if(ksGlobalTextLanguage == LANGUAGE_FRENCH)
//		file += "_fr";
//	else if(ksGlobalTextLanguage == LANGUAGE_GERMAN)
//		file += "_ge";
	file += ".txt";

	char* tmp = (char*) (path+file).data();
	websites->ReadFromFile(tmp, false);
	int sp = 15;
	websites->makeBox(300, 300, false, -1, sp);

	arrows[0][1]->TurnOn(false);
	arrows[1][1]->TurnOn(false);

	cheat_menu->Load();
	cheat_menu->TurnOnPhone(false);
}
